function decodeElevations(b64: string): Int16Array {
  const bin = atob(b64.replace(/\s/g, ''))
  const bytes = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  return new Int16Array(bytes.buffer)
}

const H = decodeElevations(B64)

export function elevationAt(lon: number, lat: number): number {
  const c = (lon - DEM.lon0) / DEM.dlon
  const r = (lat - DEM.lat0) / DEM.dlat
  if (c < 0 || r < 0 || c > DEM.cols - 1 || r > DEM.rows - 1) return 0
  const c0 = Math.floor(c)
  const r0 = Math.floor(r)
  const c1 = Math.min(DEM.cols - 1, c0 + 1)
  const r1 = Math.min(DEM.rows - 1, r0 + 1)
  const tx = c - c0
  const ty = r - r0
  const h00 = H[r0 * DEM.cols + c0]
  const h10 = H[r0 * DEM.cols + c1]
  const h01 = H[r1 * DEM.cols + c0]
  const h11 = H[r1 * DEM.cols + c1]
  return (h00 * (1 - tx) + h10 * tx) * (1 - ty) + (h01 * (1 - tx) + h11 * tx) * ty
}
